 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    if len(colors) < 2:
        return [row[:] for row in grid]
    # The outer frame is the color with the largest connected rectangular footprint.
    bboxes = {}
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        bboxes[color] = (min(r for r, c in pts), min(c for r, c in pts),
                         max(r for r, c in pts), max(c for r, c in pts))
    outer = max(colors, key=lambda col: (bboxes[col][2]-bboxes[col][0]+1) * (bboxes[col][3]-bboxes[col][1]+1))
    r0, c0, r1, c1 = bboxes[outer]
    inner_colors = colors - {outer}
    inner = max(inner_colors, key=lambda col: sum(v == col for row in grid for v in row))
    ir0, ic0, ir1, ic1 = bboxes[inner]
    thickness = min(ir0-r0, r1-ir1, ic0-c0, c1-ic1)
    # Expand the frame's bounding rectangle by its thickness, filling the new
    # area with the color of the central patch while retaining the original frame.
    out = [row[:] for row in grid]
    for r in range(max(0, r0-thickness), min(h, r1+thickness+1)):
        for c in range(max(0, c0-thickness), min(w, c1+thickness+1)):
            if not (r0 <= r <= r1 and c0 <= c <= c1 and grid[r][c] == outer):
                out[r][c] = inner
    return out

