        return [row[:] for row in grid]
    points = {}
    for color in colors:
        points[color] = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    outer = max(colors, key=lambda col: len(points[col]))
    inner = next(col for col in colors if col != outer)
    r0 = min(r for r, c in points[outer]); r1 = max(r for r, c in points[outer])
    c0 = min(c for r, c in points[outer]); c1 = max(c for r, c in points[outer])
    ir0 = min(r for r, c in points[inner]); ir1 = max(r for r, c in points[inner])
    ic0 = min(c for r, c in points[inner]); ic1 = max(c for r, c in points[inner])
    ih, iw = ir1 - ir0 + 1, ic1 - ic0 + 1
    # A square center motif expands by its side length; an elongated motif
    # expands by half its shorter side, rounded upward.
    pad = ih if ih == iw else (min(ih, iw) + 1) // 2
    out = [row[:] for row in grid]
    for r in range(max(0, r0 - pad), min(h, r1 + pad + 1)):
        for c in range(max(0, c0 - pad), min(w, c1 + pad + 1)):
